/* =====================================================================
   engine.graphql.js  —  Engine.GraphQL   (blueprint §14 — API transport)

   Generates a real GraphQL layer over the same entity model that the REST
   backend already exposes: an SDL schema, resolvers backed by the data
   layer + auth, a zero-dependency executor (`src/graphql/execute.js` —
   queries + mutations + arguments + nested selections + variables; no
   fragments/subscriptions), a `/graphql` handler the generated server
   mounts, and `test/graphql.test.js` that `runEvidence()` runs.

   window.Engine.GraphQL
     generate(spec)  -> { 'src/graphql/…': content, 'test/graphql.test.js': … }
   ===================================================================== */
(function () {
  'use strict';
  var Engine = window.Engine || (window.Engine = {});
  var GQL_TYPE = { id: 'ID', text: 'String', longtext: 'String', int: 'Int', float: 'Float', bool: 'Boolean', timestamp: 'String', ref: 'ID' };

  function resources(s) {
    return (s.entities || []).filter(function (e) { return ['user', 'session', 'job'].indexOf(e.name) < 0; });
  }
  function cap(x) { return x.charAt(0).toUpperCase() + x.slice(1); }

  /* ---------------- SDL schema ---------------- */
  function schemaSDL(s) {
    var lines = ['# GraphQL schema — generated by CodeSovereign', ''];
    if (s.auth) lines.push('type User { id: ID!, email: String!, role: String! }', 'type AuthPayload { token: String!, user: User! }', '');
    resources(s).forEach(function (e) {
      var fs = ['  id: ID!', '  createdAt: String'];
      (e.fields || []).forEach(function (f) {
        if (['id', 'createdAt', 'updatedAt'].indexOf(f.name) >= 0) return;
        fs.push('  ' + f.name + ': ' + (GQL_TYPE[f.type] || 'String') + (f.required ? '!' : ''));
      });
      lines.push('type ' + cap(e.name) + ' {', fs.join(',\n'), '}', '');
    });
    var q = ['type Query {'];
    if (s.auth) q.push('  me: User');
    resources(s).forEach(function (e) {
      q.push('  ' + e.table + '(limit: Int): [' + cap(e.name) + '!]!');
      q.push('  ' + e.name + '(id: ID!): ' + cap(e.name));
    });
    q.push('}');
    var m = ['type Mutation {'];
    if (s.auth) m.push('  register(email: String!, password: String!): AuthPayload', '  login(email: String!, password: String!): AuthPayload');
    resources(s).forEach(function (e) {
      var args = (e.fields || []).filter(function (f) { return ['id', 'createdAt', 'updatedAt'].indexOf(f.name) < 0 && !(f.type === 'ref' && f.ref === 'user'); })
        .map(function (f) { return f.name + ': ' + (GQL_TYPE[f.type] || 'String') + (f.required ? '!' : ''); });
      m.push('  create' + cap(e.name) + '(' + args.join(', ') + '): ' + cap(e.name));
      m.push('  delete' + cap(e.name) + '(id: ID!): Boolean');
    });
    m.push('}');
    lines.push(q.join('\n'), '', m.join('\n'), '', 'schema { query: Query, mutation: Mutation }', '');
    return lines.join('\n');
  }

  /* ---------------- resolvers ---------------- */
  function resolvers(s) {
    var out = [
      "'use strict';",
      "// GraphQL resolvers — thin wrappers over the same data layer + auth the REST API uses.",
      "const db = require('../db');",
      s.auth ? "const auth = require('../auth');" : "",
      "",
      "async function ctxUser(ctx) {",
      s.auth ? "  const h = (ctx.headers && (ctx.headers.authorization || ctx.headers.Authorization)) || '';\n  const t = h.replace(/^Bearer\\s+/i, '');\n  return t ? await auth.userFromToken(t).catch(() => null) : null;" : "  return null;",
      "}",
      "function requireOwner(row, user) { if (row && user && row.ownerId && String(row.ownerId) !== String(user.id) && user.role !== 'admin') throw new Error('forbidden'); return row; }",
      "",
      "const Query = {",
      s.auth ? "  me: (_a, _args, ctx) => ctxUser(ctx)," : "",
      resources(s).map(function (e) {
        return "  " + e.table + ": async (_a, args) => (await db.list('" + e.name + "', { limit: Math.min(Number(args.limit || 100), 500) })).rows,\n" +
               "  " + e.name + ": (_a, args) => db.get('" + e.name + "', args.id),";
      }).join('\n'),
      "};",
      "",
      "const Mutation = {",
      s.auth ? "  register: async (_a, args) => { const r = await auth.register(args.email, args.password); return { token: r.token, user: r.user }; },\n  login: async (_a, args) => { const r = await auth.login(args.email, args.password); return { token: r.token, user: r.user }; }," : "",
      resources(s).map(function (e) {
        var owned = (e.fields || []).some(function (f) { return f.type === 'ref' && f.ref === 'user'; });
        return "  create" + cap(e.name) + ": async (_a, args, ctx) => {\n" +
               "    const u = await ctxUser(ctx);" + (s.auth ? " if (!u) throw new Error('unauthorized');" : "") + "\n" +
               "    return db.create('" + e.name + "', Object.assign({}, args" + (owned ? ", { ownerId: u && u.id }" : "") + "));\n" +
               "  },\n" +
               "  delete" + cap(e.name) + ": async (_a, args, ctx) => {\n" +
               "    const u = await ctxUser(ctx); const row = await db.get('" + e.name + "', args.id); if (!row) return false;\n" +
               "    requireOwner(row, u); await db.remove('" + e.name + "', args.id); return true;\n" +
               "  },";
      }).join('\n'),
      "};",
      "",
      "module.exports = { Query, Mutation };",
      ""
    ].filter(function (l) { return l !== ''; }).join('\n');
    return out;
  }

  /* ---------------- zero-dep executor ---------------- */
  function executor() {
    return [
      "'use strict';",
      "// Minimal GraphQL executor: queries + mutations + arguments + variables +",
      "// nested selection sets. No fragments / directives / subscriptions.",
      "function tokenize(src) {",
      "  const re = /\\s+|#[^\\n]*|([{}():,=\\[\\]!$])|(\"(?:[^\"\\\\]|\\\\.)*\")|([A-Za-z_][A-Za-z0-9_]*)|(-?\\d+\\.\\d+|-?\\d+)/g;",
      "  const out = []; let m;",
      "  while ((m = re.exec(src))) {",
      "    if (m[1]) out.push({ t: 'punc', v: m[1] });",
      "    else if (m[2]) out.push({ t: 'str', v: JSON.parse(m[2]) });",
      "    else if (m[3]) out.push({ t: 'name', v: m[3] });",
      "    else if (m[4] != null) out.push({ t: 'num', v: Number(m[4]) });",
      "  }",
      "  return out;",
      "}",
      "function parse(src) {",
      "  const tk = tokenize(src); let i = 0;",
      "  const peek = () => tk[i], next = () => tk[i++];",
      "  const expect = (v) => { const n = next(); if (!n || n.v !== v) throw new Error('expected ' + v + ' got ' + (n && n.v)); };",
      "  function value() {",
      "    const n = peek();",
      "    if (n.t === 'str' || n.t === 'num') { next(); return { kind: 'const', value: n.v }; }",
      "    if (n.v === '$') { next(); return { kind: 'var', name: next().v }; }",
      "    if (n.v === 'true' || n.v === 'false') { next(); return { kind: 'const', value: n.v === 'true' }; }",
      "    if (n.v === 'null') { next(); return { kind: 'const', value: null }; }",
      "    if (n.v === '[') { next(); const a = []; while (peek().v !== ']') { a.push(value()); if (peek().v === ',') next(); } next(); return { kind: 'list', items: a }; }",
      "    if (n.t === 'name') { next(); return { kind: 'const', value: n.v }; }  // enum-ish",
      "    throw new Error('bad value ' + n.v);",
      "  }",
      "  function args() {",
      "    const a = {}; if (!peek() || peek().v !== '(') return a; next();",
      "    while (peek().v !== ')') { const k = next().v; expect(':'); a[k] = value(); if (peek().v === ',') next(); }",
      "    next(); return a;",
      "  }",
      "  function selectionSet() {",
      "    expect('{'); const sels = [];",
      "    while (peek() && peek().v !== '}') {",
      "      let alias = null, name = next().v;",
      "      if (peek() && peek().v === ':') { next(); alias = name; name = next().v; }",
      "      const a = args();",
      "      let sub = null; if (peek() && peek().v === '{') sub = selectionSet();",
      "      sels.push({ name, alias, args: a, sub });",
      "      if (peek() && peek().v === ',') next();",
      "    }",
      "    expect('}'); return sels;",
      "  }",
      "  let op = 'query', varDefs = [];",
      "  if (peek() && (peek().v === 'query' || peek().v === 'mutation')) {",
      "    op = next().v;",
      "    if (peek() && peek().t === 'name') next();  // operation name",
      "    if (peek() && peek().v === '(') { next(); while (peek().v !== ')') { expect('$'); const vn = next().v; expect(':'); const tn = next().v; if (peek().v === '!') next(); varDefs.push(vn); if (peek().v === ',') next(); } next(); }",
      "  }",
      "  return { op, selections: selectionSet() };",
      "}",
      "function coerce(node, vars) {",
      "  if (node.kind === 'const') return node.value;",
      "  if (node.kind === 'var') return vars[node.name];",
      "  if (node.kind === 'list') return node.items.map((x) => coerce(x, vars));",
      "  return null;",
      "}",
      "async function resolveSelections(sels, rootVal, resolverMap, vars, ctx) {",
      "  const out = {};",
      "  for (const sel of sels) {",
      "    const key = sel.alias || sel.name;",
      "    const a = {}; for (const k in sel.args) a[k] = coerce(sel.args[k], vars);",
      "    let val;",
      "    const fn = resolverMap && resolverMap[sel.name];",
      "    if (typeof fn === 'function') val = await fn(rootVal, a, ctx);",
      "    else if (rootVal && sel.name in rootVal) val = typeof rootVal[sel.name] === 'function' ? await rootVal[sel.name](rootVal, a, ctx) : rootVal[sel.name];",
      "    else val = null;",
      "    if (sel.sub && val != null) {",
      "      if (Array.isArray(val)) val = await Promise.all(val.map((v) => resolveSelections(sel.sub, v, null, vars, ctx)));",
      "      else val = await resolveSelections(sel.sub, val, null, vars, ctx);",
      "    }",
      "    out[key] = val === undefined ? null : val;",
      "  }",
      "  return out;",
      "}",
      "async function execute(schemaResolvers, query, variables, ctx) {",
      "  try {",
      "    const doc = parse(query);",
      "    const rootMap = doc.op === 'mutation' ? schemaResolvers.Mutation : schemaResolvers.Query;",
      "    const data = await resolveSelections(doc.selections, {}, rootMap, variables || {}, ctx || {});",
      "    return { data };",
      "  } catch (e) { return { errors: [{ message: String(e && e.message || e) }] }; }",
      "}",
      "module.exports = { execute, parse, tokenize };",
      ""
    ].join('\n');
  }

  function handler() {
    return [
      "'use strict';",
      "const { execute } = require('./execute');",
      "const resolvers = require('./resolvers');",
      "// mount at POST /graphql (and GET for a tiny GraphiQL-free health check).",
      "async function graphqlHandler(req, res, body) {",
      "  if (req.method === 'GET') { res.writeHead(200, { 'content-type': 'application/json' }); return res.end(JSON.stringify({ ok: true, hint: 'POST { query, variables } here' })); }",
      "  let payload = {};",
      "  try { payload = JSON.parse(body || '{}'); } catch (_) { res.writeHead(400, { 'content-type': 'application/json' }); return res.end('{\"errors\":[{\"message\":\"invalid JSON\"}]}'); }",
      "  const out = await execute(resolvers, payload.query || '', payload.variables || {}, { headers: req.headers });",
      "  res.writeHead(200, { 'content-type': 'application/json' });",
      "  res.end(JSON.stringify(out));",
      "}",
      "module.exports = { graphqlHandler };",
      ""
    ].join('\n');
  }

  function test(s) {
    var e = resources(s)[0];
    var owned = e && (e.fields || []).some(function (f) { return f.type === 'ref' && f.ref === 'user'; });
    var field = e && (e.fields || []).filter(function (f) { return ['id', 'createdAt'].indexOf(f.name) < 0 && !(f.type === 'ref' && f.ref === 'user'); })[0];
    var createArgs = field ? (field.name + ': ' + (field.type === 'int' || field.type === 'float' ? '7' : '"x"')) : '';
    return [
      "'use strict';",
      "process.env.DATA_DIR = require('node:path').join(require('node:os').tmpdir(), 'test-gql-' + process.pid);",
      "const test = require('node:test');",
      "const assert = require('node:assert');",
      "const db = require('../src/db');",
      "const { execute } = require('../src/graphql/execute');",
      "const resolvers = require('../src/graphql/resolvers');",
      s.auth ? "const auth = require('../src/auth');" : "",
      "",
      "test('graphql executor: parse + query + mutation + variables', async () => {",
      "  await db.reset(); await db.migrate();",
      s.auth ? "  const reg = await auth.register('g@t.co', 'password12'); const ctx = { headers: { authorization: 'Bearer ' + reg.token } };" : "  const ctx = { headers: {} };",
      e ? "  const created = await execute(resolvers, 'mutation($n: String){ create" + cap(e.name) + "(" + createArgs + ") { id" + (field ? ' ' + field.name : '') + " } }', {}, ctx);\n" +
          "  assert.ok(!created.errors, JSON.stringify(created.errors));\n" +
          "  assert.ok(created.data.create" + cap(e.name) + ".id, 'mutation returned an id');\n" +
          "  const listed = await execute(resolvers, '{ " + e.table + "(limit: 10) { id } }', {}, ctx);\n" +
          "  assert.equal(listed.data." + e.table + ".length, 1, 'query returns the created row');\n" +
          "  const del = await execute(resolvers, 'mutation($id: ID!){ delete" + cap(e.name) + "(id: $id) }', { id: created.data.create" + cap(e.name) + ".id }, ctx);\n" +
          "  assert.equal(del.data.delete" + cap(e.name) + ", true, 'delete mutation works');"
        : "  const q = await execute(resolvers, '{ __unused }', {}, ctx); assert.ok(q);",
      s.auth ? "  const me = await execute(resolvers, '{ me { email role } }', {}, ctx);\n  assert.equal(me.data.me.email, 'g@t.co', 'me resolver reads the token');" : "",
      "  const bad = await execute(resolvers, '{ nonexistentField }', {}, ctx);",
      "  assert.ok(bad.data && bad.data.nonexistentField === null, 'unknown field resolves null, does not crash');",
      "  await db.reset();",
      "});",
      "",
      "test('the /graphql schema SDL is present', () => {",
      "  const fs = require('fs'); const path = require('path');",
      "  const sdl = fs.readFileSync(path.join(__dirname, '..', 'src', 'graphql', 'schema.graphql'), 'utf8');",
      "  assert.match(sdl, /type Query/); assert.match(sdl, /type Mutation/);",
      "});",
      ""
    ].filter(function (l) { return l !== ''; }).join('\n');
  }

  function generate(spec) {
    var s = spec || {};
    return {
      'src/graphql/schema.graphql': schemaSDL(s),
      'src/graphql/schema.js': "'use strict';\nmodule.exports = " + JSON.stringify(schemaSDL(s)) + ";\n",
      'src/graphql/resolvers.js': resolvers(s),
      'src/graphql/execute.js': executor(),
      'src/graphql/handler.js': handler(),
      'test/graphql.test.js': test(s)
    };
  }

  Engine.GraphQL = { generate: generate, schemaSDL: schemaSDL };
  console.info('[GraphQL] GraphQL layer generator ready — Engine.GraphQL');
})();
